import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int) -> str:
    """Convert an integer to a base-36 string."""
    if n == 0:
        return '0'
    result = []
    while n > 0:
        result.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(result))


def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    return int(s, 36)


def main():
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print('ORD-0000')
        return

    last_id = lines[-1]
    # Expect format "ORD-XXXX"
    suffix = last_id.split('-')[1]
    next_num = from_base36(suffix) + 1
    next_suffix = to_base36(next_num).rjust(4, '0')
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

