"""Read the most recent order id from ids.txt and print the next one."""

import sys

BASE36_DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded uppercase base-36 string."""
    chars = []
    for _ in range(width):
        chars.append(BASE36_DIGITS[n % 36])
        n //= 36
    return "".join(reversed(chars))


def base36_decode(s: str) -> int:
    """Decode an uppercase base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36_DIGITS.index(ch)
    return n


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("Error: ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last_line = lines[-1]
    if not last_line.startswith("ORD-") or len(last_line) != 8:
        print(f"Error: invalid id format: {last_line!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_line[4:]  # e.g. "243G"
    try:
        num = base36_decode(suffix)
    except ValueError:
        print(f"Error: invalid base-36 suffix: {suffix!r}", file=sys.stderr)
        sys.exit(1)

    next_num = num + 1
    next_suffix = base36_encode(next_num)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

