import pathlib

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    if n == 0:
        return ALPHABET[0]
    result = []
    while n > 0:
        result.append(ALPHABET[n % 36])
        n //= 36
    return "".join(reversed(result))


def from_base36(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 36 + ALPHABET.index(ch.upper())
    return n


def main() -> None:
    text = pathlib.Path("ids.txt").read_text()
    lines = [line.strip() for line in text.splitlines() if line.strip()]

    if not lines:
        # No issued IDs yet; start from zero
        next_num = 0
    else:
        last_id = lines[-1]
        suffix = last_id.split("-", 1)[1]
        last_num = from_base36(suffix)
        next_num = last_num + 1

    next_suffix = to_base36(next_num).zfill(4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

