import os

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert an integer to a base36 string."""
    if n == 0:
        return "0"
    chars = []
    while n > 0:
        chars.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(chars))


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    n = 0
    for c in s:
        n = n * 36 + BASE36.index(c)
    return n


def main():
    ids_path = os.path.join(os.getcwd(), "ids.txt")
    last_id = None
    with open(ids_path) as f:
        for line in f:
            line = line.strip()
            if line:
                last_id = line

    if last_id is None:
        # No IDs yet, start from the beginning
        code = "0000"
    else:
        suffix = last_id.split("-", 1)[1]
        num = from_base36(suffix)
        code = to_base36(num + 1).zfill(4)

    print(f"ORD-{code}")


if __name__ == "__main__":
    main()

