#!/usr/bin/env python3
"""Validate orders.json: every order must have a non-empty id and amount > 0."""

import json
import sys


def main():
    try:
        with open("orders.json") as f:
            orders = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading orders.json: {e}", file=sys.stderr)
        sys.exit(1)

    if not isinstance(orders, list):
        print("Error: orders.json must contain a JSON array", file=sys.stderr)
        sys.exit(1)

    found_problem = False

    for i, order in enumerate(orders):
        order_id = order.get("id", "")
        amount = order.get("amount")

        if not isinstance(order_id, str) or not order_id.strip():
            print(f"Order at index {i}: empty or missing id")
            found_problem = True
            # Use the raw id for the problem line if it's a non-empty non-string
            order_id = str(order_id) if order_id else "<missing>"

        if not isinstance(amount, (int, float)) or amount <= 0:
            print(f"Order {order_id}: amount must be greater than zero")
            found_problem = True

    if found_problem:
        sys.exit(1)

    print("All orders are valid.")


if __name__ == "__main__":
    main()

