"""Read measurements from inbox/*.txt and write summary to report.txt."""

from pathlib import Path


def main() -> None:
    measurements: list[int] = []
    for txt_file in sorted(Path("inbox").glob("*.txt")):
        for line in txt_file.read_text().strip().splitlines():
            line = line.strip()
            if line:
                measurements.append(int(line))

    n = len(measurements)
    t = sum(measurements)
    a = t / n if n else 0.0

    report = Path("report.txt")
    report.write_text(
        f"entries {n}\n"
        f"total {t}\n"
        f"average {a:.2f}\n"
    )


if __name__ == "__main__":
    main()

