#!/usr/bin/env python3
"""Generate manifest.json: a mapping of every file under release/ to its SHA-256 hex digest."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_file(path: str) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for root, _dirs, files in os.walk(RELEASE_DIR):
        for name in sorted(files):
            full_path = os.path.join(root, name)
            # Use forward-slash relative path as the key
            rel_path = os.path.relpath(full_path).replace(os.sep, "/")
            manifest[rel_path] = sha256_file(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_FILE} with {len(manifest)} entry(s).")


if __name__ == "__main__":
    main()

