"""List report files in order."""

import os
import re


def report_sort_key(name: str) -> tuple[int, ...]:
    """Extract numeric parts from a report filename for natural ordering."""
    parts = re.findall(r"\d+", name)
    return tuple(int(p) for p in parts)


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(__file__), "reports")
    if not os.path.isdir(reports_dir):
        return

    files = [f for f in os.listdir(reports_dir) if os.path.isfile(os.path.join(reports_dir, f))]
    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
