import os
import glob
from collections import Counter

PUNCTUATION = set(".,;:!?")
DOCS_DIR = "docs"
OUTPUT_FILE = "counts.txt"


def strip_punctuation(word: str) -> str:
    return word.strip("".join(PUNCTUATION))


def main():
    counter = Counter()

    txt_files = glob.glob(os.path.join(DOCS_DIR, "**", "*.txt"), recursive=True)

    for filepath in txt_files:
        with open(filepath, encoding="utf-8") as f:
            for line in f:
                for raw_word in line.split():
                    word = strip_punctuation(raw_word.lower())
                    if word:
                        counter[word] += 1

    with open(OUTPUT_FILE, "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")


if __name__ == "__main__":
    main()

