"""Count word occurrences in all .txt files under docs/ and write counts.txt."""

import os
import re

punctuation = '.,;:!?'

counts = {}

# Walk through docs/ directory
for root, dirs, files in os.walk('docs'):
    for fname in files:
        if fname.endswith('.txt'):
            path = os.path.join(root, fname)
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    # Split into words on whitespace
                    for raw_word in line.split():
                        word = raw_word.lower().strip(punctuation)
                        # Only count if something remains
                        if word:
                            counts[word] = counts.get(word, 0) + 1

# Write sorted output
with open('counts.txt', 'w', encoding='utf-8') as out:
    for word in sorted(counts):
        out.write(f'{word} {counts[word]}\n')

