"""Rotate app.log: move entries older than 7 days before AS_OF to archive.log."""

import sys
from datetime import datetime, timezone

def parse_timestamp(line: str) -> datetime | None:
    """Extract YYYY-MM-DD HH:MM:SS from the start of a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF")
        sys.exit(1)

    as_of_ts = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff_dt = datetime.fromtimestamp(as_of_ts - 7 * 24 * 60 * 60, tz=timezone.utc)

    with open("app.log", "r") as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        if not line.strip():
            kept.append(line)
            continue
        dt = parse_timestamp(line)
        if dt is None:
            kept.append(line)
            continue
        if dt < cutoff_dt:
            archived.append(line)
        else:
            kept.append(line)

    if archived:
        with open("archive.log", "a") as f:
            f.writelines(archived)

    with open("app.log", "w") as f:
        f.writelines(kept)

    print(f"Moved {len(archived)} entries to archive.log, kept {len(kept)} entries in app.log.")

if __name__ == "__main__":
    main()

