        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 3600  # 7 days before AS_OF

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        lines = []

    fresh = []
    stale = []

    for line in lines:
        line = line.rstrip("\n")
        if not line:
            continue
        # Each line: YYYY-MM-DD HH:MM:SS <message>
        ts_str = line[:19]
        try:
            dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
            dt = dt.replace(tzinfo=timezone.utc)
        except ValueError:
            # If line doesn't parse, treat as stale (archive it)
            stale.append(line)
            continue

        entry_ts = int(dt.timestamp())
        if entry_ts < cutoff:
            stale.append(line)
        else:
            fresh.append(line)

    if stale:
        with open("archive.log", "a") as f:
            for line in stale:
                f.write(line + "\n")

    with open("app.log", "w") as f:
        for line in fresh:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

